// 文件: LocalDictionary.swift — 内置离线小词典
// 职责：内置 350+ 个四级高频词条（词目、音标、英文释义、中文释义、例句），
//       完全离线可用；提供按单词查询的静态方法，供 DictionaryService 本地兜底使用。
import Foundation

/// 词典词条（本地离线）
public struct WordEntryDict: Codable, Hashable, Sendable {
    public var word: String            // 词目（小写）
    public var phonetic: String?       // 音标（IPA）
    public var definitions: [String]   // 英文释义
    public var translation: String?    // 中文释义
    public var examples: [String]      // 例句

    public init(word: String, phonetic: String? = nil, definitions: [String],
                translation: String? = nil, examples: [String] = []) {
        self.word = word
        self.phonetic = phonetic
        self.definitions = definitions
        self.translation = translation
        self.examples = examples
    }
}

/// 紧凑构造辅助（仅本文件使用，缩短词条字面量）
private func w(_ word: String, _ phonetic: String, _ definitions: [String],
               _ translation: String, _ examples: [String]) -> WordEntryDict {
    WordEntryDict(word: word, phonetic: phonetic, definitions: definitions,
                  translation: translation, examples: examples)
}

