    /// 词目索引（小写 -> 词条），首次访问时构建
    private static let index: [String: WordEntryDict] = {
        var dict: [String: WordEntryDict] = [:]
        for entry in entries { dict[entry.word.lowercased()] = entry }
        return dict
    }()

    /// 按单词查询本地词条（大小写不敏感；未收录返回 nil）
    public static func entries(for word: String) -> WordEntryDict? {
        let key = word.trimmingCharacters(in: .whitespacesAndNewlines).lowercased()
        guard !key.isEmpty else { return nil }
        return index[key]
    }
